import{_ as e,o as l,c as t,a2 as s}from"./chunks/framework.CNDaxUod.js";const h=JSON.parse('{"title":"Changelog: V1.6 > V2","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),i={name:"changelog.md"};function o(n,a,r,u,c,m){return l(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="changelog-v1-6-v2" tabindex="-1">Changelog: V1.6 &gt; V2 <a class="header-anchor" href="#changelog-v1-6-v2" aria-label="Permalink to &quot;Changelog: V1.6 &gt; V2&quot;">​</a></h1><p>Thank you for using the SCTP! We updated to V2 on the 22nd of September - download the new mod files via the website.</p><h2 id="website" tabindex="-1">Website <a class="header-anchor" href="#website" aria-label="Permalink to &quot;Website&quot;">​</a></h2><details class="details custom-block"><summary>Mapart!</summary><ul><li>The website now has the full in-game mapart museum, but digital!</li><li>As mapart seller, you can verify your account to manage your own maps!</li></ul></details><details class="details custom-block"><summary>Collections!</summary><ul><li>You can now mark mapart and rares as having them in your collection!</li><li>You can share your collection with others via a link, and you can see a ton of stats by clicking on your username!</li></ul></details><details class="details custom-block"><summary>Marketplace additions!</summary><ul><li>You can now post jobs on the marketplace!</li><li>You can review listings/sellers now!</li></ul></details><details class="details custom-block"><summary>Rare-dle!</summary><ul><li>You can now play a variation on wordle, but based on our SC rares catalog: rare-dle!</li><li>A new rare is chosen every day!</li></ul></details><details class="details custom-block"><summary>QOL/fixes</summary><ul><li>Hide columns from the search table</li><li>Price filter can now convert to diamond-equivalent</li><li>Typo suggestions where needed</li><li>Mapart of the day on the home page</li><li>Navigation bar redesigned</li></ul></details><h2 id="mod" tabindex="-1">Mod <a class="header-anchor" href="#mod" aria-label="Permalink to &quot;Mod&quot;">​</a></h2><details class="details custom-block"><summary>Mapart Scanner</summary><ul><li>The mod now has a built in mapart scanning feature that uploads straight to the gallery!</li></ul></details><details class="details custom-block"><summary>Watchlist QOL</summary><ul><li>You can now ignore listings in your watchlist</li><li>General usage of watchlist has been improved.</li></ul></details><details class="details custom-block"><summary>In-game reporting</summary><ul><li>You can now report all listings via in-game menu&#39;s!</li></ul></details><details class="details custom-block"><summary>Small extras</summary><ul><li>Rare rentals info can now be toggled on for shulkers</li><li>Fly and rank tokens no longer redeem automatically</li></ul></details>',13)])])}const g=e(i,[["render",o]]);export{h as __pageData,g as default};
